            .orElseThrow(() -> new BadCredentialsException("invalid_signature"));

        Instant requestTime = Instant.parse(request.getHeader("X-Date"));
        if (Duration.between(requestTime, clock.instant()).abs().compareTo(Duration.ofMinutes(5)) > 0) {
